import React, { useCallback, useState } from 'react';
import * as SecureStore from 'expo-secure-store';
import axios from 'axios';
import { ScrollView, ActivityIndicator, TouchableOpacity } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import tw from 'twrnc';
import Searchbar from '@/components/Searchbar';
import LanguageList from '@/components/LanguageList';
import CategorySection from '@/components/CategorySection';
import { useThemeColor } from '@/hooks/useThemeColor';
import { ThemedText } from '@/components/ThemedText';
import { ThemedView } from '@/components/ThemedView';
import { useRouter } from 'expo-router';
import Constants from 'expo-constants';

export default function Main() {
  const router = useRouter();
  const [books, setBooks] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [role, setRole] = useState(null);

  const backgroundColor = useThemeColor({}, 'background');
  const textColor = useThemeColor({}, 'text');
  const primaryColor = useThemeColor({}, 'primary');
  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;

  const fetchBooks = useCallback(async () => {
    if (!apiUrl) {
      setError("API URL is not defined.");
      setLoading(false);
      return;
    }

    try {
      const token = await SecureStore.getItemAsync('authToken');
      const role = await SecureStore.getItemAsync('userRole');
      setRole(role);

      if (!token) {
        throw new Error('No authentication token found');
      }

      const response = await axios.get(`${apiUrl}/books`, {
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
      });

      setBooks(response.data.books || []);
    } catch (error) {
      setError(error.message || "Failed to fetch books.");
    } finally {
      setLoading(false);
    }
  }, [apiUrl]);

  // ✅ Auto-refresh books when screen is focused
  useFocusEffect(
    useCallback(() => {
      fetchBooks();
    }, [fetchBooks])
  );

  if (loading) {
    return (
      <ThemedView style={[tw`flex-1 items-center justify-center`, { backgroundColor }]}>
        <ActivityIndicator size="large" color={primaryColor} />
        <ThemedText style={{ color: textColor, marginTop: 10 }}>Loading audiobooks</ThemedText>
      </ThemedView>
    );
  }

  if (error) {
    return (
      <ThemedView style={[tw`flex-1 items-center justify-center`, { backgroundColor }]}>
        <ThemedText style={{ color: textColor }}>Error: {error}</ThemedText>
      </ThemedView>
    );
  }

  return (
    <ThemedView style={[tw`flex-1`, { backgroundColor }]}>
      <ThemedView style={tw`px-6 pt-15 pb-1`}>
        <ThemedText type='title' style={{ color: textColor }}>Iweohun</ThemedText>
        <ThemedText style={[tw`text-lg font-semibold`, { color: primaryColor }]}>
          Orating African literature
        </ThemedText>
      </ThemedView>

      <ScrollView>
        <Searchbar />

        {role == 'creator' && (
          <ThemedView style={tw`flex-row justify-end mb-4 mr-5`}>
            <TouchableOpacity
              style={[
                tw`rounded-3xl px-4 py-2`,
                { backgroundColor: primaryColor }
              ]}
              onPress={() => router.push('/addBook')}
            >
              <ThemedText style={tw`text-white text-lg font-semibold text-center`}>
                ✚ Create
              </ThemedText>
            </TouchableOpacity>
          </ThemedView>
        )}

        <LanguageList />

        {/* Category Sections */}
        <ThemedView style={tw`mb-10 w-full px-5`}>
          {['History & Biographies', 'Fiction', 'Romance', 'Kids', 'Personal Development', 'Adventure & Thrillers'].map((category) => (
            <CategorySection
              key={category}
              title={category}
              books={books.filter(book => book?.category === category)}
              textColor={textColor}
              primaryColor={primaryColor}
            />
          ))}
        </ThemedView>
      </ScrollView>
    </ThemedView>
  );
}
